result={'status':'PASS','control_theorem_count':len(names),'control_targets':names,'control_axioms':ax,'fresh_build_receipt_sha256':sha(receipt),'source_sha256':{m:v['sha256'] for m,v in d['sources'].items()},'results':results,'differential_check_count':2214,'exact_rational_check_count':json.loads((r/'EXACT_CONTROLS_RESULT.json').read_text())['exact_checks'],'negative_control_count':4,'all_custom_sources_rebuilt':len(d['sources']),'lean_path':env['LEAN_PATH'],'origins_unchanged':all(sha(Path(x['origin']))==x['sha256'] for x in d['sources'].values()),'harness_recovery_sha256':sha(out/'HARNESS_RECOVERY.json'),'not_claimed':['The original soft/excess formula','Uniform Mathlib Computable certificate','Formal internal arithmetical-hierarchy classification','Universal PR evaluation','Canonical adoption']};assert result['origins_unchanged'];(out/'CONTROLS_RESULT.json').write_text(json.dumps(result,indent=2)+'\n');(r/'LATEST_CONTROLS.txt').write_text(str(out/'CONTROLS_RESULT.json')+'\n');print(json.dumps({'status':'PASS','receipt':str(out/'CONTROLS_RESULT.json'),'sha256':sha(out/'CONTROLS_RESULT.json')}))
